function cleanText(s) {
  return (s || '')
    .toString()
    .replace(/\s+/g, ' ')
    .trim();
}

function short(s, n = 220) {
  const t = cleanText(s);
  return t.length > n ? t.slice(0, n).trim() + '…' : t;
}

function tokens(s) {
  return cleanText(s)
    .toLowerCase()
    .match(/[a-zа-я0-9]{3,}/gi)?.filter(t => !STOP.has(t)) || [];
}

function tset(s) {
  return new Set(tokens(s));
}

function jaccard(a, b) {
  const A = tset(a);
  const B = tset(b);
  if (!A.size && !B.size) return 0;

  let inter = 0;
  for (const x of A) {
    if (B.has(x)) inter++;
  }

  return inter / (A.size + B.size - inter || 1);
}

function tfidf(docs) {
  const toks = docs.map(tokens);
  const df = {};

  for (const docTokens of toks) {
    for (const w of new Set(docTokens)) {
      df[w] = (df[w] || 0) + 1;
    }
  }

  const N = docs.length || 1;
  const idf = {};

  for (const w in df) {
    idf[w] = Math.log((N + 1) / (df[w] + 1)) + 1;
  }

