  for (const k in b) {
    nb += b[k] * b[k];
  }

  return dot / ((Math.sqrt(na) * Math.sqrt(nb)) || 1);
}

function polarity(t) {
  t = cleanText(t).toLowerCase();

  const POS = [
    'improve','improves','improved','outperform','outperforms','increase',
    'increases','higher','better','reduce error','reduces','superior',
    'gain','boost','enhance','effective','state-of-the-art','sota'
  ];

  const NEG = [
    'no significant','not significant','fails','fail','degrade','degrades',
    'worse','lower','decrease','inferior','no improvement','did not',
    'limitation','limited','challenging'
  ];

  let s = 0;
  POS.forEach(w => { if (t.includes(w)) s++; });
  NEG.forEach(w => { if (t.includes(w)) s--; });

  return s > 0 ? 1 : s < 0 ? -1 : 0;
}

function mulberry32(seed) {
  return function () {
    seed |= 0;
    seed = seed + 0x6D2B79F5 | 0;
    let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

