  const k = Math.max(2, Math.ceil(Math.sqrt(corpus.length / 2)));

  const rnd = mulberry32(42);
  const idxs = [...Array(corpus.length).keys()];

  for (let i = idxs.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [idxs[i], idxs[j]] = [idxs[j], idxs[i]];
  }

  let cent = [];
  for (let i = 0; i < k; i++) {
    cent.push({ ...vectors[idxs[i]] });
  }

  let assign = new Array(corpus.length).fill(0);

  for (let iter = 0; iter < 10; iter++) {
    for (let i = 0; i < vectors.length; i++) {
      let best = 0;
      let bs = -1;

      for (let c = 0; c < k; c++) {
        const s = cosine(vectors[i], cent[c]);
        if (s > bs) {
          bs = s;
          best = c;
        }
      }

      assign[i] = best;
    }

    const sum = Array.from({ length: k }, () => ({}));
    const cnt = new Array(k).fill(0);

    for (let i = 0; i < vectors.length; i++) {
      const c = assign[i];
      cnt[c]++;

      for (const w in vectors[i]) {
        sum[c][w] = (sum[c][w] || 0) + vectors[i][w];
      }
    }

    for (let c = 0; c < k; c++) {
      if (cnt[c]) {
        for (const w in sum[c]) {
          sum[c][w] /= cnt[c];
        }
        cent[c] = sum[c];
      }
    }
  }

  for (let c = 0; c < k; c++) {
    const members = corpus.filter((_, i) => assign[i] === c);

    if (!members.length) continue;

    const label = Object.entries(cent[c])
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3)
      .map(x => x[0]);

    clusters.push({
      cluster: c,
      label,
      size: members.length,
